CREATE OR REPLACE FUNCTION public.check_goods_in_storage_unit(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
DECLARE
  v_location TEXT;
  v_lot TEXT;
  v_deactivated BOOLEAN;
  v_moved BOOLEAN;
BEGIN
  IF p_operation <> 'UPDATE' THEN
    RETURN;
  END IF;
  v_deactivated := COALESCE((p_old->>'active')::boolean, true)
    AND NOT COALESCE((p_new->>'active')::boolean, true);
  v_moved := (p_new->'locationId') IS DISTINCT FROM (p_old->'locationId');
  IF NOT v_deactivated AND NOT v_moved THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  SELECT l."name" INTO v_location
  FROM "location" l
  WHERE l."companyId" = p_old->>'companyId'
    AND (l."inspectionStorageUnitId" = p_old->>'id' OR l."rejectedStorageUnitId" = p_old->>'id')
  ORDER BY l."name"
  LIMIT 1;
  IF FOUND THEN
    RAISE EXCEPTION '% is a goods-in storage unit of %. Choose another unit in Settings → Quality first.',
      COALESCE(p_new->>'name', p_new->>'id'), v_location;
  END IF;

  SELECT COALESCE(i."inspectionId", i."id") INTO v_lot
  FROM "inspection" i
  WHERE i."storageUnitId" = p_old->>'id'
    AND i."companyId" = p_old->>'companyId'
    AND i."status" IN ('Pending', 'In Progress', 'Partial')
    AND public.inspection_lot_holds(i."id", i."status", i."acceptedQuantity")
  ORDER BY i."inspectionId"
  LIMIT 1;
  IF FOUND THEN
    IF NOT EXISTS (SELECT 1 FROM "company" c WHERE c."id" = p_old->>'companyId') THEN
      RETURN;
    END IF;
    RAISE EXCEPTION '% holds stock of inspection lot %. Quality must decide the lot first.',
      COALESCE(p_new->>'name', p_new->>'id'), v_lot;
  END IF;
END;
$function$;

CREATE OR REPLACE FUNCTION public.check_location_goods_in_storage_units(p_table text, p_operation text, p_new jsonb, p_old jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public', 'extensions'
AS $function$
-- Goods-in inspection hold (spec .ai/specs/2026-11-03-goods-in-inspection-hold.md).
-- A location's inspection and rejected storage units must be its own: the
-- foreign keys only check that the unit exists, not that it belongs to this
-- location and company. A plain RAISE (P0001), so the API shows the text.
DECLARE
  v_column TEXT;
  v_unit   TEXT;
  v_found  RECORD;
BEGIN
  IF p_operation NOT IN ('INSERT', 'UPDATE') THEN
    RETURN;
  END IF;
  IF current_setting('app.inspection_release', true) = 'on'
     OR current_setting('app.sync_in_progress', true) = 'true' THEN
    RETURN;
  END IF;

  IF p_new->>'inspectionStorageUnitId' IS NOT NULL
     AND p_new->>'inspectionStorageUnitId' = p_new->>'rejectedStorageUnitId' THEN
    RAISE EXCEPTION 'The inspection and rejected storage units must be two different units.';
  END IF;

  FOREACH v_column IN ARRAY ARRAY['inspectionStorageUnitId', 'rejectedStorageUnitId'] LOOP
    v_unit := p_new->>v_column;
    CONTINUE WHEN v_unit IS NULL;
    CONTINUE WHEN p_operation = 'UPDATE'
      AND v_unit IS NOT DISTINCT FROM p_old->>v_column
      AND (p_new->>'companyId') IS NOT DISTINCT FROM (p_old->>'companyId');

    SELECT su."name", su."active" INTO v_found
    FROM "storageUnit" su
    WHERE su."id" = v_unit
      AND su."companyId" = p_new->>'companyId'
      AND su."locationId" = p_new->>'id';
    IF NOT FOUND THEN
      RAISE EXCEPTION 'The goods-in storage unit must belong to this location.';
    END IF;
    IF NOT COALESCE(v_found."active", true) THEN
      RAISE EXCEPTION '% is inactive. A goods-in storage unit must be active.', v_found."name";
    END IF;
  END LOOP;
END;
$function$;
